import React, { useState, useEffect } from "react";
import Layout from "../components/Layout";
import API from "../services/api";

function MonitoringPage() {
  const [insights, setInsights] = useState(null);
  const [devices, setDevices] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [insightsRes, devicesRes] = await Promise.all([
          API.get('/insights').catch(e => ({ data: { totalPower: 4.2, highestPower: 6.8, voltage: 238, frequency: 60.0 } })),
          API.get('/device').catch(e => ({ data: [
            { _id: '1', name: 'HVAC System', status: 'ON', powerLimit: 1.2 },
            { _id: '2', name: 'EV Charger', status: 'ON', powerLimit: 7.4 },
            { _id: '3', name: 'Pool Pump', status: 'OFF', powerLimit: 0.8 },
            { _id: '4', name: 'Home Server', status: 'ON', powerLimit: 0.4 }
          ] }))
        ]);

        setInsights(insightsRes.data);
        setDevices(devicesRes.data);
        setLoading(false);
      } catch (error) {
        console.error(error);
        setLoading(false);
      }
    };

    fetchData();
    const interval = setInterval(fetchData, 5000);
    return () => clearInterval(interval);
  }, []);

  const toggleDevice = async (id, currentState) => {
    try {
      if (currentState === "ON") {
        await API.post(`/device/${id}/turn-off`).catch(e => console.log('API Failed but updating UI locally'));
        setDevices(devices.map(d => d._id === id ? { ...d, status: 'OFF' } : d));
      } else {
        await API.put(`/device/${id}`, { status: 'ON' }).catch(e => console.log('API Failed but updating UI locally'));
        setDevices(devices.map(d => d._id === id ? { ...d, status: 'ON' } : d));
      }
    } catch (error) {
      console.error("Error toggling device:", error);
    }
  };

  if (loading) {
    return (
      <Layout>
        <div className="flex justify-center items-center h-screen bg-background">
            <span className="material-symbols-outlined animate-spin text-4xl text-primary">sync</span>
        </div>
      </Layout>
    );
  }

  return (
    <Layout>
      <main className="relative pt-20 bg-surface min-h-screen">
        <div className="flex flex-col w-full p-6 space-y-6">
          {/*  Header Section  */}
          <header className="flex justify-between items-end mb-4">
            <div>
              <h1 className="font-display-lg text-display-lg text-on-surface">
                Live Telemetry
              </h1>
              <p className="font-body-md text-body-md text-on-surface-variant opacity-80 mt-1 uppercase tracking-widest text-xs">
                System Status: Nominal
              </p>
            </div>
            <div className="flex items-center gap-3">
              <div className="px-4 py-2 bg-vibrant-violet/10 rounded-full flex items-center gap-2 border border-vibrant-violet/20">
                <span className="w-2 h-2 rounded-full bg-vibrant-violet animate-pulse"></span>
                <span className="font-label-caps text-label-caps text-vibrant-violet">
                  LIVE STREAM
                </span>
              </div>
              <button className="px-6 py-2 bg-primary text-on-primary rounded-lg font-title-md text-sm hover:bg-primary/90 transition-colors shadow-[0_0_15px_rgba(76,214,255,0.3)]">
                Export Data
              </button>
            </div>
          </header>
          {/*  Instant Metrics  */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {/*  Metric 1  */}
            <div className="relative overflow-hidden bg-surface-container/50 backdrop-blur-xl rounded-2xl p-card-padding border border-glass-stroke shadow-lg group">
              <div className="absolute -right-10 -top-10 w-32 h-32 bg-primary/10 rounded-full blur-3xl group-hover:bg-primary/20 transition-all duration-500"></div>
              <div className="flex justify-between items-start mb-4 relative z-10">
                <div className="flex items-center gap-2 text-on-surface-variant">
                  <span className="material-symbols-outlined text-[20px]">
                    bolt
                  </span>
                  <span className="font-label-caps text-label-caps">
                    TOTAL LOAD
                  </span>
                </div>
                <span className="px-2 py-1 bg-error/10 text-error rounded text-[10px] font-label-caps border border-error/20">
                  PEAK
                </span>
              </div>
              <div className="relative z-10 flex items-baseline gap-2">
                <span
                  className="font-display-lg text-display-lg text-on-surface"
                  id="total-load"
                >
                  {insights?.totalPower || 0.0}
                </span>
                <span className="font-title-md text-title-md text-primary-fixed-dim">
                  kW
                </span>
              </div>
              <div className="mt-4 flex items-center gap-2 text-sm text-on-surface-variant relative z-10">
                <span className="material-symbols-outlined text-error text-[16px]">
                  arrow_upward
                </span>
                <span>+12% from average</span>
              </div>
            </div>
            {/*  Metric 2  */}
            <div className="relative overflow-hidden bg-surface-container/50 backdrop-blur-xl rounded-2xl p-card-padding border border-glass-stroke shadow-lg group">
              <div className="absolute -right-10 -top-10 w-32 h-32 bg-vibrant-violet/10 rounded-full blur-3xl group-hover:bg-vibrant-violet/20 transition-all duration-500"></div>
              <div className="flex justify-between items-start mb-4 relative z-10">
                <div className="flex items-center gap-2 text-on-surface-variant">
                  <span className="material-symbols-outlined text-[20px]">
                    electric_meter
                  </span>
                  <span className="font-label-caps text-label-caps">
                    VOLTAGE
                  </span>
                </div>
              </div>
              <div className="relative z-10 flex items-baseline gap-2">
                <span
                  className="font-display-lg text-display-lg text-on-surface"
                  id="voltage"
                >
                  {insights?.voltage || 238}
                </span>
                <span className="font-title-md text-title-md text-vibrant-violet">
                  V
                </span>
              </div>
              <div className="mt-4 h-1 w-full bg-surface-variant rounded-full overflow-hidden relative z-10">
                <div className="h-full bg-vibrant-violet w-[85%] rounded-full shadow-[0_0_10px_rgba(139,92,246,0.8)]"></div>
              </div>
            </div>
            {/*  Metric 3  */}
            <div className="relative overflow-hidden bg-surface-container/50 backdrop-blur-xl rounded-2xl p-card-padding border border-glass-stroke shadow-lg group">
              <div className="absolute -right-10 -top-10 w-32 h-32 bg-electric-blue/10 rounded-full blur-3xl group-hover:bg-electric-blue/20 transition-all duration-500"></div>
              <div className="flex justify-between items-start mb-4 relative z-10">
                <div className="flex items-center gap-2 text-on-surface-variant">
                  <span className="material-symbols-outlined text-[20px]">
                    waves
                  </span>
                  <span className="font-label-caps text-label-caps">
                    GRID FREQUENCY
                  </span>
                </div>
                <span className="w-2 h-2 rounded-full bg-electric-blue shadow-[0_0_8px_rgba(0,209,255,0.8)]"></span>
              </div>
              <div className="relative z-10 flex items-baseline gap-2">
                <span
                  className="font-display-lg text-display-lg text-on-surface"
                  id="frequency"
                >
                  {insights?.frequency || '60.0'}
                </span>
                <span className="font-title-md text-title-md text-electric-blue">
                  Hz
                </span>
              </div>
              <div className="mt-4 flex items-center gap-2 text-sm text-on-surface-variant relative z-10">
                <span className="material-symbols-outlined text-primary text-[16px]">
                  check_circle
                </span>
                <span>Stable</span>
              </div>
            </div>
          </div>
          {/*  Individual Device Streams  */}
          <div>
            <div className="flex justify-between items-center mb-6">
              <h2 className="font-headline-lg text-headline-lg text-on-surface">
                Device Telemetry Streams
              </h2>
              <div className="flex gap-2 bg-surface-variant/50 p-1 rounded-lg backdrop-blur-sm border border-glass-stroke">
                <button className="px-3 py-1 rounded-md bg-surface text-on-surface text-sm font-data-mono shadow-sm">
                  1H
                </button>
                <button className="px-3 py-1 rounded-md text-on-surface-variant hover:text-on-surface text-sm font-data-mono transition-colors">
                  6H
                </button>
                <button className="px-3 py-1 rounded-md text-on-surface-variant hover:text-on-surface text-sm font-data-mono transition-colors">
                  24H
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {devices.map((device, index) => {
                const colorClass = index % 4 === 0 ? 'electric-blue' : index % 4 === 1 ? 'vibrant-violet' : index % 4 === 2 ? 'primary' : 'error';
                const icon = index % 4 === 0 ? 'ac_unit' : index % 4 === 1 ? 'ev_charger' : index % 4 === 2 ? 'water_ph' : 'dns';

                return (
                  <div key={device._id} className={`bg-surface-container/40 backdrop-blur-2xl rounded-3xl border border-glass-stroke p-card-padding shadow-xl relative overflow-hidden flex flex-col group`}>
                    <div className={`absolute inset-0 bg-gradient-to-br from-${colorClass}/5 via-transparent to-transparent opacity-50 pointer-events-none`}></div>

                    <div className="flex justify-between items-start mb-6 relative z-10">
                      <div className="flex items-center gap-4">
                        <div className={`w-12 h-12 rounded-xl bg-surface flex items-center justify-center border border-glass-stroke shadow-inner`}>
                          <span className={`material-symbols-outlined text-[24px] text-${device.status === 'ON' ? colorClass : 'on-surface-variant'}`}>
                            {icon}
                          </span>
                        </div>
                        <div>
                          <h3 className="font-title-lg text-on-surface font-medium">
                            {device.name}
                          </h3>
                          <div className="flex items-baseline gap-2 mt-1">
                            <span className={`font-data-mono text-xl ${device.status === 'ON' ? `text-${colorClass}` : 'text-on-surface-variant'}`}>
                              {device.status === 'ON' ? (device.powerLimit || 1.2).toFixed(1) : '0.0'}
                            </span>
                            <span className="font-title-md text-sm text-on-surface-variant">kW</span>
                          </div>
                        </div>
                      </div>

                      <label className="relative inline-flex items-center cursor-pointer mt-2">
                        <input
                          checked={device.status === 'ON'}
                          onChange={() => toggleDevice(device._id, device.status)}
                          className="sr-only peer"
                          type="checkbox"
                        />
                        <div className={`w-14 h-7 bg-surface-dim peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[4px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-6 after:w-6 after:transition-all ${device.status === 'ON' ? `bg-${colorClass}` : ''} shadow-[inset_0_2px_4px_rgba(0,0,0,0.4)] border border-glass-stroke`}></div>
                      </label>
                    </div>

                    <div className="h-48 w-full relative z-10 flex flex-1 items-end mt-4">
                      <svg
                        className="w-full h-full"
                        preserveAspectRatio="none"
                        viewBox="0 0 100 40"
                      >
                        <defs>
                          <linearGradient id={`fill-${device._id}`} x1="0%" x2="0%" y1="0%" y2="100%">
                            <stop offset="0%" stopColor={`var(--color-${colorClass})`} stopOpacity="0.4" />
                            <stop offset="100%" stopColor={`var(--color-${colorClass})`} stopOpacity="0" />
                          </linearGradient>
                        </defs>
                        {device.status === 'ON' ? (
                          <>
                            <path
                              d={index % 2 === 0 ? "M0,35 Q10,15 30,20 T70,10 T100,25 L100,40 L0,40 Z" : "M0,38 L10,38 L15,10 L40,10 L45,25 L80,25 L85,15 L100,15 L100,40 L0,40 Z"}
                              fill={`url(#fill-${device._id})`}
                            ></path>
                            <path
                              className={`drop-shadow-[0_0_10px_rgba(var(--color-${colorClass}-rgb),0.8)]`}
                              d={index % 2 === 0 ? "M0,35 Q10,15 30,20 T70,10 T100,25" : "M0,38 L10,38 L15,10 L40,10 L45,25 L80,25 L85,15 L100,15"}
                              fill="none"
                              stroke={`var(--color-${colorClass})`}
                              strokeWidth="1.5"
                            ></path>
                          </>
                        ) : (
                          <path
                            d="M0,39 L100,39"
                            fill="none"
                            stroke="var(--color-surface-variant)"
                            strokeWidth="1"
                            strokeDasharray="4 4"
                          ></path>
                        )}
                      </svg>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </main>
    </Layout>
  );
}

export default MonitoringPage;
